# D24 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d24_flow.py   (인터넷·외부 프로세스 불필요)
#   [대체 경로] 진짜 MCP SDK·자식 프로세스 대신, 같은 파일 안의 모의 서버 2개와 모의 클라이언트가
#   JSON-RPC 문자열(한 줄)을 주고받는다. 도구 목록 → 합치기 → 확인 정책 → 호출까지 한 번에 확인.
import json


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


class Server:
    """모의 MCP 서버: 한 줄 JSON-RPC 요청을 받아 한 줄 응답을 돌려준다."""
    def __init__(self, name: str, tools: dict):
        self.name, self.tools = name, tools            # tools: 이름 → (설명, 읽기전용?, 함수)

    def handle(self, line: str) -> str | None:
        req = json.loads(line)
        if "id" not in req:                            # 알림(notification)에는 응답하지 않는다
            return None
        m, p = req["method"], req.get("params", {})
        if m == "initialize":
            result = {"serverInfo": {"name": self.name}, "capabilities": {"tools": {}}}
        elif m == "tools/list":
            result = {"tools": [{"name": n, "description": d, "annotations": {"readOnlyHint": ro}} for n, (d, ro, _) in self.tools.items()]}
        elif m == "tools/call":
            result = {"content": [{"type": "text", "text": json.dumps(self.tools[p["name"]][2](**p["arguments"]), ensure_ascii=False)}]}
        else:
            return json.dumps({"jsonrpc": "2.0", "id": req["id"], "error": {"code": -32601, "message": "Method not found"}})
        return json.dumps({"jsonrpc": "2.0", "id": req["id"], "result": result}, ensure_ascii=False)


class Client:
    def __init__(self, server: Server):
        self.server, self.n = server, 0
        self.request("initialize")
        server.handle(json.dumps({"jsonrpc": "2.0", "method": "notifications/initialized"}))

    def request(self, method: str, params: dict | None = None) -> dict:
        self.n += 1
        line = json.dumps({"jsonrpc": "2.0", "id": self.n, "method": method, "params": params or {}})
        return json.loads(self.server.handle(line))["result"]


BOOKINGS = []
db = Server("hanbit-db", {"list_slots": ("빈 시간 조회", True, lambda date: ["10:00", "14:00"]),
                          "book_slot": ("예약 만들기", False, lambda date, time: BOOKINGS.append((date, time)) or "예약 완료")})
cal = Server("my-calendar", {"list_events": ("내 일정 조회", True, lambda date: ["13:00 회의"])})
hub = {}
for srv in (db, cal):                                  # 서버마다 클라이언트 1개, 도구 이름에 서버 이름을 붙여 합친다
    c = Client(srv)
    for t in c.request("tools/list")["tools"]:
        hub[f"{srv.name}__{t['name']}"] = (c, t)
print("합친 도구 목록:", list(hub))


def call(full: str, args: dict, confirmed: bool = False):
    c, t = hub[full]
    if not t["annotations"]["readOnlyHint"] and not confirmed:
        return "확인 필요"                             # 읽기 전용이 아니면 사용자 확인 전에는 실행하지 않음
    return json.loads(c.request("tools/call", {"name": t["name"], "arguments": args})["content"][0]["text"])


r1 = call("my-calendar__list_events", {"date": "2026-12-01"})
r2 = call("hanbit-db__book_slot", {"date": "2026-12-01", "time": "14:00"})
r3 = call("hanbit-db__book_slot", {"date": "2026-12-01", "time": "14:00"}, confirmed=True)
print(r1, r2, r3, BOOKINGS)
check(len(hub) == 3 and r1 == ["13:00 회의"] and r2 == "확인 필요" and r3 == "예약 완료" and len(BOOKINGS) == 1,
      "서버 둘의 도구가 한 목록이 되고, 쓰기 도구는 확인 뒤에만 실행돼요.")

