// D24 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d24_flow.ts   (인터넷·외부 프로세스 불필요)
//   [대체 경로] 진짜 MCP SDK·자식 프로세스 대신, 같은 파일 안의 모의 서버 2개와 모의 클라이언트가
//   JSON-RPC 문자열(한 줄)을 주고받는다. 도구 목록 → 합치기 → 확인 정책 → 호출까지 한 번에 확인.
type Fn = (args: Record<string, string>) => unknown;
type ToolDef = [string, boolean, Fn]; // 설명, 읽기전용?, 함수
type Tool = { name: string; description: string; annotations: { readOnlyHint: boolean } };

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class Server {
  name: string;
  tools: Record<string, ToolDef>;
  constructor(name: string, tools: Record<string, ToolDef>) {
    this.name = name;
    this.tools = tools;
  }
  handle(line: string): string | null {
    const req = JSON.parse(line);
    if (!("id" in req)) return null; // 알림(notification)에는 응답하지 않는다
    const m: string = req.method;
    const p = req.params ?? {};
    let result: unknown;
    if (m === "initialize") result = { serverInfo: { name: this.name }, capabilities: { tools: {} } };
    else if (m === "tools/list") {
      result = { tools: Object.entries(this.tools).map(([name, [description, ro]]) => ({ name, description, annotations: { readOnlyHint: ro } })) };
    } else if (m === "tools/call") {
      result = { content: [{ type: "text", text: JSON.stringify(this.tools[p.name][2](p.arguments)) }] };
    } else return JSON.stringify({ jsonrpc: "2.0", id: req.id, error: { code: -32601, message: "Method not found" } });
    return JSON.stringify({ jsonrpc: "2.0", id: req.id, result });
  }
}

class Client {
  server: Server;
  n = 0;
  constructor(server: Server) {
    this.server = server;
    this.request("initialize");
    server.handle(JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }));
  }
  request(method: string, params: Record<string, unknown> = {}): any {
    this.n += 1;
    const line = JSON.stringify({ jsonrpc: "2.0", id: this.n, method, params });
    return JSON.parse(this.server.handle(line) as string).result;
  }
}

const BOOKINGS: string[][] = [];
const db = new Server("hanbit-db", {
  list_slots: ["빈 시간 조회", true, () => ["10:00", "14:00"]],
  book_slot: ["예약 만들기", false, (a) => { BOOKINGS.push([a.date, a.time]); return "예약 완료"; }],
});
const cal = new Server("my-calendar", { list_events: ["내 일정 조회", true, () => ["13:00 회의"]] });
const hub: Record<string, [Client, Tool]> = {};
for (const srv of [db, cal]) { // 서버마다 클라이언트 1개, 도구 이름에 서버 이름을 붙여 합친다
  const c = new Client(srv);
  for (const t of c.request("tools/list").tools as Tool[]) hub[`${srv.name}__${t.name}`] = [c, t];
}
console.log("합친 도구 목록:", Object.keys(hub));

function call(full: string, args: Record<string, string>, confirmed: boolean = false): unknown {
  const [c, t] = hub[full];
  if (!t.annotations.readOnlyHint && !confirmed) return "확인 필요"; // 읽기 전용이 아니면 사용자 확인 전에는 실행하지 않음
  return JSON.parse(c.request("tools/call", { name: t.name, arguments: args }).content[0].text);
}

const r1 = call("my-calendar__list_events", { date: "2026-12-01" }) as string[];
const r2 = call("hanbit-db__book_slot", { date: "2026-12-01", time: "14:00" });
const r3 = call("hanbit-db__book_slot", { date: "2026-12-01", time: "14:00" }, true);
console.log(r1, r2, r3, BOOKINGS);
check(Object.keys(hub).length === 3 && r1[0] === "13:00 회의" && r2 === "확인 필요" && r3 === "예약 완료" && BOOKINGS.length === 1, "서버 둘의 도구가 한 목록이 되고, 쓰기 도구는 확인 뒤에만 실행돼요.");

